"use client";
import { useCallback, useEffect, useRef, useState } from "react";
import { api } from "@/lib/api";
import { applyEvent, type ChatState } from "@/lib/chat";
import type { ConversationSummary } from "@/lib/types";
import { Shell } from "@/components/shell";
import { MessageList } from "@/components/message-list";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

function ConversationList({ items, activeId, onSelect, onNew }: { items: ConversationSummary[]; activeId: string | null; onSelect: (id: string) => void; onNew: () => void }) {
  return (
    <div className="flex h-full flex-col gap-2 p-2">
      <Button onClick={onNew}>New chat</Button>
      <ul className="min-h-0 flex-1 space-y-1 overflow-y-auto" aria-label="Conversations">
        {items.map((c) => (
          <li key={c.id}>
            <button onClick={() => onSelect(c.id)}
              className={cn("block min-h-11 w-full rounded-md px-3 py-2 text-left text-sm hover:bg-slate-100", c.id === activeId && "bg-slate-100")}>
              <span className="block truncate font-medium">{c.title || "New chat"}</span>
              <span className="block truncate text-xs text-muted">{c.preview}</span>
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

function Chat() {
  const [list, setList] = useState<ConversationSummary[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [state, setState] = useState<ChatState>({ messages: [], draft: null });
  const [text, setText] = useState("");
  const [drawer, setDrawer] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const bottom = useRef<HTMLDivElement>(null);
  const streaming = state.draft !== null;

  const load = useCallback(async (id: string) => {
    const c = await api.conversation(id);
    setState({ messages: c.messages, draft: null });
  }, []);

  const refreshList = useCallback(async () => { setList(await api.conversations()); }, []);

  useEffect(() => {
    (async () => {
      const items = await api.conversations();
      setList(items);
      if (items[0]) { setActiveId(items[0].id); await load(items[0].id); }
    })().catch((e) => setError(e.message));
  }, [load]);

  useEffect(() => { bottom.current?.scrollIntoView?.({ block: "end" }); }, [state]);

  async function select(id: string) { setDrawer(false); setActiveId(id); setError(null); await load(id); }
  async function newChat() {
    const c = await api.createConversation();
    setList((l) => [c, ...l]); setActiveId(c.id); setState({ messages: [], draft: null }); setDrawer(false);
  }

  async function send(e: React.FormEvent) {
    e.preventDefault();
    const t = text.trim();
    if (!t || streaming) return;
    setText(""); setError(null);
    let id = activeId;
    try {
      if (!id) { const c = await api.createConversation(); id = c.id; setActiveId(id); }
      let s = state;
      await api.sendMessage(id, t, (ev) => { s = applyEvent(s, ev); setState(s); });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Request failed");
    }
    // Stream over (done, error or disconnect): the server state wins.
    if (id) await load(id).catch(() => setState((s) => ({ ...s, draft: null })));
    refreshList().catch(() => {});
  }

  return (
    <div className="relative flex h-full">
      <aside className="hidden w-72 shrink-0 border-r border-border bg-card md:block">
        <ConversationList items={list} activeId={activeId} onSelect={select} onNew={newChat} />
      </aside>
      {drawer && (
        <div className="fixed inset-0 z-20 md:hidden" role="dialog" aria-modal="true" aria-label="Conversations">
          <div className="absolute inset-0 bg-black/40" onClick={() => setDrawer(false)} />
          <div className="absolute inset-y-0 left-0 w-72 max-w-[85vw] bg-card shadow-xl">
            <ConversationList items={list} activeId={activeId} onSelect={select} onNew={newChat} />
          </div>
        </div>
      )}
      <section className="flex min-w-0 flex-1 flex-col">
        <div className="border-b border-border px-2 md:hidden">
          <Button variant="ghost" onClick={() => setDrawer(true)} aria-label="Open conversations">☰ Conversations</Button>
        </div>
        <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden p-3 sm:p-4">
          {state.messages.length === 0 && !state.draft && (
            <p className="mt-10 text-center text-sm text-muted">Where would you like to fly? Try “I want to fly from Guangzhou to Lima”.</p>
          )}
          <MessageList messages={state.messages} draft={state.draft} onBooked={() => activeId && load(activeId)} />
          {error && <p role="alert" className="mt-3 text-sm text-danger">{error}</p>}
          <div ref={bottom} />
        </div>
        <form onSubmit={send} className="flex gap-2 border-t border-border bg-card p-2 sm:p-3">
          <input value={text} onChange={(e) => setText(e.target.value)} placeholder="Where do you want to go?" aria-label="Message"
            className="min-h-11 min-w-0 flex-1 rounded-md border border-border px-3 text-base" />
          <Button type="submit" disabled={streaming || !text.trim()}>Send</Button>
        </form>
      </section>
    </div>
  );
}

export default function ChatPage() {
  return <Shell>{() => <Chat />}</Shell>;
}
import type { Conversation, ConversationSummary, Message, SseEvent, TicketCard, Trace, User } from "./types";
import { readSse } from "./sse";

export class ApiError extends Error {
  constructor(public status: number, public code: string, message: string) {
    super(message);
  }
}

async function req<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`/api${path}`, {
    ...init,
    credentials: "same-origin",
    headers: { "Content-Type": "application/json", ...(init?.headers ?? {}) },
  });
  const body = await res.json().catch(() => ({}));
  if (!res.ok) {
    const e = (body as { error?: { code?: string; message?: string } }).error;
    throw new ApiError(res.status, e?.code ?? "error", e?.message ?? res.statusText);
  }
  return body as T;
}

export const api = {
  config: () => req<{ dev_login: boolean; google_client_id: string | null }>("/config"),
  login: (username: string, password: string) =>
    req<User>("/auth/dev", { method: "POST", body: JSON.stringify({ username, password }) }),
  logout: () => req<{ ok: boolean }>("/auth/logout", { method: "POST" }),
  me: () => req<User>("/me"),
  conversations: () => req<{ conversations: ConversationSummary[] }>("/conversations").then((r) => r.conversations),
  createConversation: () => req<ConversationSummary>("/conversations", { method: "POST", body: "{}" }),
  conversation: (id: string) => req<Conversation>(`/conversations/${id}`),
  book: (quoteId: string, nonce: string) =>
    req<{ ticket: TicketCard; message: Message }>(`/quotes/${quoteId}/book`, {
      method: "POST",
      body: JSON.stringify({ nonce }),
    }),
  trace: (quoteId: string) => req<Trace>(`/quotes/${quoteId}/trace`),
  tickets: () => req<{ tickets: TicketCard[] }>("/tickets").then((r) => r.tickets),

  /** POST a user message and stream SSE events. Resolves when the stream ends. */
  async sendMessage(conversationId: string, text: string, onEvent: (e: SseEvent) => void, signal?: AbortSignal) {
    const res = await fetch(`/api/conversations/${conversationId}/messages`, {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text }),
      signal,
    });
    if (!res.ok || !res.body) {
      const body = await res.json().catch(() => ({}));
      const e = (body as { error?: { code?: string; message?: string } }).error;
      throw new ApiError(res.status, e?.code ?? "error", e?.message ?? res.statusText);
    }
    await readSse(res.body, onEvent);
  },
};
import type { SseEvent } from "./types";

/** Incremental SSE parser: feed text chunks, get complete events. */
export class SseParser {
  private buf = "";
  push(chunk: string): SseEvent[] {
    this.buf += chunk.replace(/\r\n/g, "\n");
    const out: SseEvent[] = [];
    let i: number;
    while ((i = this.buf.indexOf("\n\n")) >= 0) {
      const block = this.buf.slice(0, i);
      this.buf = this.buf.slice(i + 2);
      const ev = parseBlock(block);
      if (ev) out.push(ev);
    }
    return out;
  }
}

function parseBlock(block: string): SseEvent | null {
  let event = "";
  const data: string[] = [];
  for (const line of block.split("\n")) {
    if (line.startsWith(":")) continue;
    if (line.startsWith("event:")) event = line.slice(6).trim();
    else if (line.startsWith("data:")) data.push(line.slice(5).replace(/^ /, ""));
  }
  if (!event) return null;
  try {
    return { event, data: data.length ? JSON.parse(data.join("\n")) : {} } as SseEvent;
  } catch {
    return null;
  }
}

/** Read an SSE response body, calling onEvent for each event. */
export async function readSse(body: ReadableStream<Uint8Array>, onEvent: (e: SseEvent) => void): Promise<void> {
  const reader = body.getReader();
  const dec = new TextDecoder();
  const parser = new SseParser();
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    for (const e of parser.push(dec.decode(value, { stream: true }))) onEvent(e);
  }
  for (const e of parser.push("\n\n")) onEvent(e);
}
import type { Card, Message, SseEvent } from "./types";

export type Draft = { text: string; status: string | null; cards: Card[]; error: string | null };
export type ChatState = { messages: Message[]; draft: Draft | null };

export const emptyDraft: Draft = { text: "", status: null, cards: [], error: null };

/** Pure reducer: apply one SSE event. `done` replaces the draft by the final server message. */
export function applyEvent(s: ChatState, e: SseEvent): ChatState {
  const d = s.draft ?? emptyDraft;
  switch (e.event) {
    case "user_message": return { messages: [...s.messages, e.data], draft: { ...emptyDraft } };
    case "status": return { ...s, draft: { ...d, status: e.data.text } };
    case "card": return { ...s, draft: { ...d, cards: [...d.cards, e.data.card] } };
    case "delta": return { ...s, draft: { ...d, text: d.text + e.data.text } };
    case "replace": return { ...s, draft: { ...d, text: e.data.text } };
    case "done": return { messages: [...s.messages, e.data.message], draft: null };
    case "error": return { ...s, draft: { ...d, status: null, error: e.data.message } };
    default: return s;
  }
}
// Mirrors docs/api/contract.md. Keep in sync through the coordinator only.
export type User = { id: string; display_name: string; auth_provider: "dev" | "google" };
export type ConversationSummary = { id: string; title: string; created_at: string; updated_at: string; preview: string };
export type Leg = { from: string; to: string; distance_display: string; distance: string };
export type CardState = {
  status: "quoted" | "presented" | "booked" | "expired" | "stale";
  bookable: boolean;
  nonce: string | null;
  ticket_id: string | null;
};
type RouteFields = {
  id: string; origin: string; destination: string; legs: Leg[]; transfers: string[];
  distance_display: string; price_display: string; distance: string; price: string;
  expires_at: string; state: CardState;
};
export type QuoteCard = RouteFields & { type: "quote" };
export type BookingRequestCard = RouteFields & { type: "booking_request" };
export type TicketCard = {
  type: "ticket"; id: string; quote_id: string; origin: string; destination: string; legs: Leg[];
  transfers: string[]; distance_display: string; price_display: string; booked_at: string;
};
export type TicketListCard = { type: "ticket_list"; count: number; filter: Record<string, string>; tickets: TicketCard[] };
export type NoServiceCard = { type: "no_service"; city: string; nearest: { city: string; distance_display: string }[] };
export type AmbiguousCityCard = {
  type: "ambiguous_city"; query: string;
  candidates: { city: string; is_hub: boolean; connected_hubs: string[] }[];
};
export type UnknownCityCard = { type: "unknown_city"; query: string; suggestions: string[] };
export type NoticeCard = {
  type: "notice"; code: "same_city" | "unreachable" | "quote_expired" | "stale"; message: string;
};
export type Card =
  | QuoteCard | BookingRequestCard | TicketCard | TicketListCard | NoServiceCard
  | AmbiguousCityCard | UnknownCityCard | NoticeCard;
export type Message = {
  id: string; role: "user" | "assistant" | "system"; text: string; cards: Card[]; created_at: string;
};
export type Conversation = ConversationSummary & { messages: Message[] };
export type Trace = {
  quote_id: string; formula: string; algorithm: string; network_fingerprint: string;
  legs: (Leg & { from_coord: [number, number]; to_coord: [number, number]; source: string })[];
  distance: string; price: string; distance_display: string; price_display: string; note: string;
};

export type SseEvent =
  | { event: "user_message"; data: Message }
  | { event: "status"; data: { text: string } }
  | { event: "card"; data: { card: Card } }
  | { event: "delta"; data: { text: string } }
  | { event: "replace"; data: { text: string } }
  | { event: "ping"; data: Record<string, never> }
  | { event: "done"; data: { message: Message } }
  | { event: "error"; data: { code: string; message: string } };
"use client";
import { useState } from "react";
import type { BookingRequestCard, QuoteCard, TicketCard, Trace } from "@/lib/types";
import { Badge, Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { api, ApiError } from "@/lib/api";

type Route = QuoteCard | BookingRequestCard | TicketCard;

const STATUS_LABEL: Record<string, { text: string; tone: "muted" | "ok" | "warn" | "danger" }> = {
  quoted: { text: "Quote", tone: "muted" },
  presented: { text: "Awaiting confirmation", tone: "warn" },
  booked: { text: "Booked", tone: "ok" },
  expired: { text: "Expired", tone: "danger" },
  stale: { text: "Out of date", tone: "danger" },
};

function Route({ card }: { card: Route }) {
  return (
    <>
      <div className="flex flex-wrap items-center gap-x-2 text-base font-semibold">
        <span>{card.origin}</span><span aria-hidden>→</span><span>{card.destination}</span>
      </div>
      <ol className="mt-3 space-y-1 text-sm" aria-label="Route legs">
        {card.legs.map((l, i) => (
          <li key={i} className="flex flex-wrap justify-between gap-x-3">
            <span>{l.from} → {l.to}</span>
            <span className="text-muted">{l.distance_display}</span>
          </li>
        ))}
      </ol>
      <p className="mt-2 text-sm text-muted">
        {card.transfers.length ? <>Transfers: {card.transfers.join(", ")}</> : <>Direct flight</>}
      </p>
      <dl className="mt-3 flex gap-6 border-t border-border pt-3 text-sm">
        <div><dt className="text-muted">Total distance</dt><dd className="font-semibold">{card.distance_display}</dd></div>
        <div><dt className="text-muted">Price</dt><dd className="font-semibold">{card.price_display}</dd></div>
      </dl>
    </>
  );
}

function TraceView({ quoteId }: { quoteId: string }) {
  const [open, setOpen] = useState(false);
  const [trace, setTrace] = useState<Trace | null>(null);
  const [err, setErr] = useState<string | null>(null);
  async function toggle() {
    const next = !open;
    setOpen(next);
    if (next && !trace) {
      try { setTrace(await api.trace(quoteId)); } catch (e) { setErr(e instanceof Error ? e.message : "Failed to load"); }
    }
  }
  return (
    <div className="mt-3">
      <Button variant="ghost" className="px-2" onClick={toggle} aria-expanded={open}>
        {open ? "Hide calculation details" : "Calculation details"}
      </Button>
      {open && (
        <div className="mt-2 space-y-2 rounded-md bg-slate-50 p-3 text-xs" data-testid="trace">
          {err && <p className="text-danger">{err}</p>}
          {!trace && !err && <p className="text-muted">Loading…</p>}
          {trace && (
            <>
              <p><span className="text-muted">Formula:</span> {trace.formula}</p>
              <p><span className="text-muted">Algorithm:</span> {trace.algorithm}</p>
              <ul className="space-y-1">
                {trace.legs.map((l, i) => (
                  <li key={i} className="break-words">
                    {l.from} ({l.from_coord.join(", ")}) → {l.to} ({l.to_coord.join(", ")}): {l.distance}
                    <span className="text-muted"> · {l.source}</span>
                  </li>
                ))}
              </ul>
              <p className="break-all">Distance: {trace.distance}</p>
              <p className="break-all">Price: {trace.price}</p>
              <p className="break-all"><span className="text-muted">Network:</span> {trace.network_fingerprint}</p>
              <p className="text-muted">{trace.note}</p>
            </>
          )}
        </div>
      )}
    </div>
  );
}

/** Quote / booking_request card. Confirm is shown only when the server says bookable and no stream is running. */
export function QuoteCardView({
  card, streaming = false, readOnly = false, onBooked,
}: { card: QuoteCard | BookingRequestCard; streaming?: boolean; readOnly?: boolean; onBooked?: () => void }) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const st = STATUS_LABEL[card.state.status] ?? STATUS_LABEL.quoted;
  const showConfirm = card.state.bookable && !!card.state.nonce && !readOnly;

  async function confirm() {
    if (!card.state.nonce) return;
    setBusy(true); setError(null);
    try {
      await api.book(card.id, card.state.nonce);
      onBooked?.();
    } catch (e) {
      setError(e instanceof ApiError ? e.message : "Booking failed");
      onBooked?.(); // server state wins: reload
    } finally {
      setBusy(false);
    }
  }

  return (
    <Card data-testid={`card-${card.type}`} className="w-full max-w-md">
      <div className="mb-2 flex items-center justify-between gap-2">
        <Badge tone={st.tone}>{st.text}</Badge>
        <span className="text-xs text-muted">Valid until {new Date(card.expires_at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</span>
      </div>
      <Route card={card} />
      {showConfirm && (
        <Button className="mt-4 w-full" onClick={confirm} disabled={streaming || busy}>
          Confirm booking
        </Button>
      )}
      {error && <p role="alert" className="mt-2 text-sm text-danger">{error}</p>}
      <TraceView quoteId={card.id} />
    </Card>
  );
}

export function TicketCardView({ card }: { card: TicketCard }) {
  return (
    <Card data-testid="card-ticket" className="w-full max-w-md border-green-300">
      <div className="mb-2 flex items-center justify-between gap-2">
        <Badge tone="ok">Ticket {card.id}</Badge>
        <span className="text-xs text-muted">Booked {new Date(card.booked_at).toLocaleString()}</span>
      </div>
      <Route card={card} />
    </Card>
  );
}
import type { Card } from "@/lib/types";
import { QuoteCardView, TicketCardView } from "./route-card";
import { AmbiguousCityCardView, NoServiceCardView, NoticeCardView, TicketListCardView, UnknownCityCardView } from "./simple-cards";

export function CardView({ card, streaming, readOnly, onBooked }: { card: Card; streaming?: boolean; readOnly?: boolean; onBooked?: () => void }) {
  switch (card.type) {
    case "quote":
    case "booking_request":
      return <QuoteCardView card={card} streaming={streaming} readOnly={readOnly} onBooked={onBooked} />;
    case "ticket": return <TicketCardView card={card} />;
    case "ticket_list": return <TicketListCardView card={card} />;
    case "no_service": return <NoServiceCardView card={card} />;
    case "ambiguous_city": return <AmbiguousCityCardView card={card} />;
    case "unknown_city": return <UnknownCityCardView card={card} />;
    case "notice": return <NoticeCardView card={card} />;
  }
}
"use client";
import { Streamdown } from "streamdown";

export function Markdown({ text, streaming = false }: { text: string; streaming?: boolean }) {
  return (
    <div className="prose-sm max-w-none break-words [&_p]:my-1 [&_ul]:list-disc [&_ul]:pl-5 [&_ol]:list-decimal [&_ol]:pl-5 [&_strong]:font-semibold">
      <Streamdown mode={streaming ? "streaming" : "static"}>{text}</Streamdown>
    </div>
  );
}
"use client";
import { useEffect, useState } from "react";
import { api } from "@/lib/api";
import type { TicketCard } from "@/lib/types";
import { Shell } from "@/components/shell";
import { TicketCardView } from "@/components/cards/route-card";

function Tickets() {
  const [tickets, setTickets] = useState<TicketCard[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => { api.tickets().then(setTickets).catch((e) => setError(e.message)); }, []);
  return (
    <div className="h-full overflow-y-auto p-3 sm:p-6">
      <h1 className="mb-3 text-lg font-semibold">My tickets</h1>
      {error && <p role="alert" className="text-danger">{error}</p>}
      {tickets?.length === 0 && <p className="text-muted">You have no tickets yet.</p>}
      <div className="space-y-3">{tickets?.map((t) => <TicketCardView key={t.id} card={t} />)}</div>
    </div>
  );
}
export default function TicketsPage() { return <Shell>{() => <Tickets />}</Shell>; }
"use client";
import Link from "next/link";
import { useEffect, useState } from "react";
import { api } from "@/lib/api";
import type { ConversationSummary } from "@/lib/types";
import { Shell } from "@/components/shell";

function History() {
  const [items, setItems] = useState<ConversationSummary[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => { api.conversations().then(setItems).catch((e) => setError(e.message)); }, []);
  return (
    <div className="h-full overflow-y-auto p-3 sm:p-6">
      <h1 className="mb-3 text-lg font-semibold">Conversation history</h1>
