              <span className="block font-medium">{c.title || "New chat"}</span>
              <span className="block text-sm text-muted">{c.preview}</span>
              <span className="block text-xs text-muted">{new Date(c.updated_at).toLocaleString()}</span>
            </Link>
          </li>
        ))}
      </ul>
