"use client";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useEffect, useState, type ReactNode } from "react";
import { api, ApiError } from "@/lib/api";
import type { User } from "@/lib/types";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

const NAV = [
  { href: "/chat", label: "Chat" },
  { href: "/tickets", label: "My tickets" },
  { href: "/history", label: "History" },
];

/** Authenticated page frame: header + nav; redirects to /login on 401. */
export function Shell({ children, headerLeft }: { children: (user: User) => ReactNode; headerLeft?: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const router = useRouter();
  const path = usePathname();

  useEffect(() => {
    api.me().then(setUser).catch((e) => {
      if (e instanceof ApiError && e.status === 401) router.replace("/login");
    });
  }, [router]);

  if (!user) return <div className="p-6 text-muted">Loading…</div>;
  return (
    <div className="flex h-dvh flex-col">
      <header className="flex items-center gap-1 border-b border-border bg-card px-2 sm:px-4">
        {headerLeft}
        <span className="mr-2 hidden font-semibold sm:inline">Ocean Above</span>
        <nav className="flex flex-1 gap-1" aria-label="Main">
          {NAV.map((n) => (
            <Link key={n.href} href={n.href}
              className={cn("inline-flex min-h-11 items-center rounded-md px-3 text-sm hover:bg-slate-100", path.startsWith(n.href) && "bg-slate-100 font-medium")}>
              {n.label}
            </Link>
          ))}
        </nav>
        <Button variant="ghost" onClick={async () => { await api.logout().catch(() => {}); router.replace("/login"); }}>
          Sign out
        </Button>
      </header>
      <div className="min-h-0 flex-1">{children(user)}</div>
    </div>
  );
}
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex min-h-11 min-w-11 items-center justify-center gap-2 rounded-md px-4 text-sm font-medium transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary disabled:cursor-not-allowed disabled:opacity-50",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-fg hover:bg-primary/90",
        outline: "border border-border bg-card hover:bg-slate-100",
        ghost: "hover:bg-slate-100",
      },
    },
    defaultVariants: { variant: "default" },
  },
);

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(({ className, variant, ...props }, ref) => (
  <button ref={ref} className={cn(buttonVariants({ variant }), className)} {...props} />
));
Button.displayName = "Button";
@import "tailwindcss";

@source "../../node_modules/streamdown/dist/*.js";

:root {
  --background: #f8fafc;
  --foreground: #0f172a;
  --muted: #64748b;
  --border: #e2e8f0;
  --card: #ffffff;
  --primary: #0369a1;
  --primary-fg: #ffffff;
  --danger: #b91c1c;
  --ok: #15803d;
  --warn: #b45309;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-muted: var(--muted);
  --color-border: var(--border);
  --color-card: var(--card);
  --color-primary: var(--primary);
  --color-primary-fg: var(--primary-fg);
  --color-danger: var(--danger);
  --color-ok: var(--ok);
  --color-warn: var(--warn);
}

html, body { height: 100%; }
body { background: var(--background); color: var(--foreground); font-family: system-ui, sans-serif; overflow-x: hidden; }
import { describe, expect, it } from "vitest";
import { render, screen } from "@testing-library/react";
import { MessageList } from "@/components/message-list";
import { conversation } from "./fixtures";

describe("message list", () => {
  it("renders the whole fixture conversation incl. markdown and every card type", () => {
    render(<MessageList messages={conversation().messages} readOnly />);
    expect(screen.getByText("I want to fly from Guangzhou to Lima")).toBeInTheDocument();
    for (const t of ["quote", "booking_request", "ticket", "ticket_list", "no_service", "ambiguous_city", "unknown_city", "notice"]) {
      expect(screen.getAllByTestId(`card-${t}`).length).toBeGreaterThan(0);
    }
  });

  it("shows status while streaming without text", () => {
    render(<MessageList messages={[]} draft={{ text: "", status: "Looking up routes…", cards: [], error: null }} />);
    expect(screen.getByRole("status")).toHaveTextContent("Looking up routes…");
  });
});
import "@testing-library/jest-dom/vitest";
import { cleanup } from "@testing-library/react";
import { afterEach } from "vitest";
afterEach(() => cleanup());
import { defineConfig } from "vitest/config";
import react from "@vitejs/plugin-react";
import path from "node:path";

export default defineConfig({
  plugins: [react()],
  resolve: { alias: { "@": path.resolve(__dirname, "src") } },
  test: { environment: "jsdom", globals: true, setupFiles: ["tests/setup.ts"], include: ["tests/**/*.test.ts?(x)"] },
});
